import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Sessions","description":"Create, resume, fork, undo, compact, share, export, and delete PrioriCode sessions — and where they live on disk.","frontmatter":{"title":"Sessions","description":"Create, resume, fork, undo, compact, share, export, and delete PrioriCode sessions — and where they live on disk."},"headers":[],"relativePath":"using/sessions.md","filePath":"using/sessions.md"}'),n={name:"using/sessions.md"};function o(l,s,r,h,d,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<p>Every conversation PrioriCode has with you is a <strong>session</strong>: a stream of messages, tool calls, file diffs, todos, and costs, all living in one database. Sessions are also where subagents do their work — each task spawns a child session you can jump into.</p><h2 id="creating-and-resuming" tabindex="-1">Creating and resuming <a class="header-anchor" href="#creating-and-resuming" aria-label="Permalink to &quot;Creating and resuming&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-_E60r" id="tab-hXosdM3" checked><label data-title="In the TUI" for="tab-hXosdM3">In the TUI</label><input type="radio" name="group-_E60r" id="tab--gD33w1"><label data-title="From the CLI" for="tab--gD33w1">From the CLI</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # new session in the current project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # jump back into the latest session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ses_…</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # resume a specific one</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # recent sessions, paginated</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # machine-readable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ses_…</span></span></code></pre></div></div></div><p>Inside the TUI: <code>/sessions</code> (or <code>&lt;leader&gt;l</code>) is the resume dialog, <code>/new</code> starts fresh, and <code>/rename</code> fixes the title. The agent auto-generates a title after your first message — usually better than what you would have typed.</p><p>Sessions form a tree: when the agent dispatches a subagent, that&#39;s a child session. Follow it with <code>&lt;leader&gt;down</code> (first child), <code>left</code>/<code>right</code> (cycle siblings), and <code>up</code> (back to the parent).</p><h2 id="fork-undo-redo" tabindex="-1">Fork, undo, redo <a class="header-anchor" href="#fork-undo-redo" aria-label="Permalink to &quot;Fork, undo, redo&quot;">​</a></h2><p>The agent went down a rabbit hole? Time-travel instead of apologizing:</p><ul><li><strong><code>/undo</code></strong> reverts the last user message and everything that followed — files on disk are restored from the snapshot, and the message text lands back in your prompt, ready to edit and resubmit.</li><li><strong><code>/redo</code></strong> steps the reverts forward again, restoring what you undid.</li><li><strong><code>/fork</code></strong> (or <code>/timeline</code> → pick a message) branches the conversation up to that point into a new session, titled <code>… (fork #N)</code>. The original stays untouched.</li><li><code>--fork</code> on the CLI does the same from the latest (or <code>--session</code>) state.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Revert state is transient: send a new message and the undo chain is cleaned up. Undo, then undo again, then act — don&#39;t undo after the fact.</p></div><h2 id="compaction" tabindex="-1">Compaction <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;Compaction&quot;">​</a></h2><p>Every model has a context window; long sessions fill it. When you approach the limit, PrioriCode <strong>compacts</strong>: it summarizes older history and keeps the recent turns verbatim.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/compact</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or /summarize — do it yourself, before you have to</span></span></code></pre></div><p>The <code>compaction</code> config block tunes the whole system — automatic vs manual, the threshold at which it fires, how much recent context survives (<code>tail_turns</code>, <code>preserve_recent_tokens</code>, <code>reserved</code>), and <code>prune</code>, which drops old tool output (the defaults keep everything; pruning saves tokens once a session gets chatty). Details in the <a href="./../reference/config.html">config reference</a>.</p><h2 id="sharing-export" tabindex="-1">Sharing &amp; export <a class="header-anchor" href="#sharing-export" aria-label="Permalink to &quot;Sharing &amp; export&quot;">​</a></h2><ul><li><code>/share</code> produces a read-only web page of the transcript (with a consent prompt the first time — read it, it&#39;s honest about what leaves your machine). <code>/unshare</code> deletes it. See <a href="./sharing.html">sharing</a>.</li><li><code>prioricode export [sessionID]</code> writes the full session as JSON; add <code>--sanitize</code> to redact transcript and file contents for bug reports.</li><li><code>prioricode import &lt;file-or-share-url&gt;</code> brings an export or a shared link back into a local session — the fastest way to reproduce someone else&#39;s debugging session.</li></ul><h2 id="usage-stats" tabindex="-1">Usage stats <a class="header-anchor" href="#usage-stats" aria-label="Permalink to &quot;Usage stats&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # last week of tokens and cost</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tools</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # which tools the agent leaned on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --models</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # per-model breakdown</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # just this project</span></span></code></pre></div><p>Totals, per-day cost, input/output/reasoning/cache tokens — straight from the session records, no account required.</p><h2 id="where-sessions-live" tabindex="-1">Where sessions live <a class="header-anchor" href="#where-sessions-live" aria-label="Permalink to &quot;Where sessions live&quot;">​</a></h2><p>Sessions, messages, parts, and todos live in a SQLite database, not in scattered JSON files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # the resolved file, e.g. ~/.local/share/prioricode/prioricode.db</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # interactive sqlite3 shell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;select id,title from session order by time_updated desc limit 10&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsv</span></span></code></pre></div><p>Different release channels use different DB files, and <code>PRIORICODE_DB</code> overrides the whole thing — the routing rules are on the <a href="./../configure/files.html">config files page</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The database contains your prompts, file contents, and diffs. It&#39;s local — but local files are still files. Back it up or wipe it like you would an SSH keychain.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./sharing.html">Sharing</a> — What a share link exposes and how to take it back. <ul><li><a href="./coordination.html">Coordination</a> — Sessions that talk to each other.</li><li><a href="./headless.html">Headless</a> — Sessions scripted from CI.</li><li><a href="./../reference/slash-commands.html">Session commands</a> — The full <code>/</code> inventory.</li></ul></li></ul>`,25)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
